/* === ОБЩАЯ КАРТОЧКА === */
.card {
  font-family: "Hiragino Kaku Gothic Pro", "Meiryo", "Noto Sans JP", Arial, sans-serif;
  font-size: 20px;
  text-align: center;
  color: #333;
  background-color: #fcfcfc;
  line-height: 1.6;
}

.nightMode .card {
  background-color: #2f2f31;
  color: #dcdcdc;
}

/* === ЛИЦЕВАЯ СТОРОНА === */
.main-word {
  font-size: 36px;
  font-weight: bold;
  color: #000;
  margin-top: 40px;
  margin-bottom: 40px;
}
.nightMode .main-word { color: #fff; }

.word-focus {
  color: rgb(255, 170, 0);
  font-weight: bold;
}

/* === ОБОРОТНАЯ СТОРОНА === */
.align-left {
  text-align: left;
  padding: 10px 20px;
  max-width: 800px;
  margin: 0 auto;
}

/* 1. Блок ЗНАЧЕНИЯ */
.meaning-box {
  background-color: #e8f4fd;
  border-left: 5px solid #3498db;
  padding: 15px;
  margin-bottom: 20px;
  font-size: 24px;
  font-weight: 600;
  border-radius: 5px;
  color: #2c3e50;
}
.nightMode .meaning-box {
  background-color: #3d4e5b;
  color: #e6f3ff;
  border-left-color: #5dade2;
}

/* 2. Блок УДАРЕНИЯ */
.reading-box {
  background-color: #fff8e1;
  border: 1px solid #ffe082;
  padding: 10px 15px;
  margin-bottom: 20px;
  border-radius: 5px;
}
.nightMode .reading-box {
  background-color: #423e35;
  border-color: #635d49;
}

.section-label {
  font-size: 14px;
  text-transform: uppercase;
  color: #f39c12;
  font-weight: bold;
  margin-bottom: 5px;
}

.reading-content {
  font-family: "Consolas", monospace;
  font-size: 18px;
  display: flex;
  align-items: center;
}

/* === СТИЛЬ ДЛЯ ЧАСТИ РЕЧИ === */
.pos-tag {
  display: inline-block;
  font-size: 14px;
  font-weight: normal;
  color: #555;
  background-color: #e0e0e0;
  padding: 4px 10px;
  border-radius: 15px;
  margin-bottom: 8px;
  text-transform: none;
}

.nightMode .pos-tag {
  background-color: #444;
  color: #ccc;
}

/* 3. Остальные разделы */
.section-container {
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 1px solid #eee;
}
.nightMode .section-container { border-bottom-color: #444; }

.section-container:last-child { border-bottom: none; }

.section-title {
  font-size: 16px;
  font-weight: bold;
  color: #7f8c8d;
  margin-bottom: 5px;
}
.nightMode .section-title { color: #aaa; }

.text-body {
  font-size: 20px;
  line-height: 1.8;
}

.examples {
  font-style: italic;
  color: #555;
  margin-left: 10px;
  border-left: 2px solid #ddd;
  padding-left: 10px;
}
.nightMode .examples { color: #bbb; border-left-color: #555; }

/* === ПРИМЕРЫ === */
.example-item {
  margin-bottom: 12px;
}

.example-item:last-child {
  margin-bottom: 0;
}

.jp {
  font-size: 21px;
  line-height: 1.8;
}

.ru {
  font-size: 18px;
  line-height: 1.7;
  color: #666;
}

.nightMode .ru {
  color: #c8c8c8;
}

.example-focus {
  color: rgb(170, 170, 127);
  font-weight: bold;
}

.nightMode .example-focus {
  color: rgb(170, 170, 127);
  font-weight: bold;
}

.meaning-focus {
  color: rgb(255, 165, 0);
  font-weight: bold;
  font-style: italic;
}

.nightMode .meaning-focus {
  color: rgb(255, 165, 0);
  font-weight: bold;
  font-style: italic;
}

/* === ДОПОЛНИТЕЛЬНО ДЛЯ КАРТИНОК === */
img {
  max-width: 100%;
  height: auto;
  border-radius: 3px;
}

/* === БЛОК ПОХОЖИХ СЛОВ === */
.similar-box {
  background-color: #f3f3f3;
  border: 1px solid #e0e0e0;
  border-left: 4px solid #9aa0a6;
  border-radius: 5px;
  padding: 12px 14px;
  margin-top: 5px;
}

.nightMode .similar-box {
  background-color: #343436;
  border-color: #4a4a4d;
  border-left-color: #8a8f98;
}

.similar-box .section-title {
  margin-bottom: 8px;
  color: #6f767d;
}

.nightMode .similar-box .section-title {
  color: #b0b0b0;
}

.similar-box .text-body {
  font-size: 20px;
  line-height: 1.9;
  color: #333;
}

.nightMode .similar-box .text-body {
  color: #e0e0e0;
}

.similar-item {
  display: inline-block;
  background-color: #ffffff;
  border: 1px solid #dddddd;
  border-radius: 14px;
  padding: 3px 10px;
  margin: 0 6px 8px 0;
  font-size: 20px;
}

.nightMode .similar-item {
  background-color: #2b2b2d;
  border-color: #555;
  color: #eeeeee;
}

/* === FSRS MEMORY STATE === */
#FSRS_status {
  display: block !important;
  width: fit-content !important;
  margin: 24px auto 0 auto !important;
  padding: 8px 12px !important;
  border-radius: 6px !important;
  background-color: #f3f3f3 !important;
  border: 1px solid #dddddd !important;
  color: #777 !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  opacity: 0.75 !important;
  text-align: left !important;
  font-family: "Consolas", monospace !important;
}

.nightMode #FSRS_status {
  background-color: #343436 !important;
  border-color: #4a4a4d !important;
  color: #aaa !important;
}
